script:
test("visit on the inclusive end date is covered and leaves 1", function () {
  assert.deepEqual(code.checkAuthorization({
    approvedVisits: 6,
    usedVisits: 4,
    startDate: "2026-02-01",
    endDate: "2026-04-30",
    visitDate: "2026-04-30"
  }), { covered: true, remaining: 1 });
});

test("visit one day after the end date is not covered and leaves 2", function () {
  assert.deepEqual(code.checkAuthorization({
    approvedVisits: 6,
    usedVisits: 4,
    startDate: "2026-02-01",
    endDate: "2026-04-30",
    visitDate: "2026-05-01"
  }), { covered: false, remaining: 2 });
});

test("visit is not covered when used equals approved and leaves 0", function () {
  assert.deepEqual(code.checkAuthorization({
    approvedVisits: 6,
    usedVisits: 6,
    startDate: "2026-02-01",
    endDate: "2026-04-30",
    visitDate: "2026-03-15"
  }), { covered: false, remaining: 0 });
});

test("visit on the inclusive start date is covered and leaves 1", function () {
  assert.deepEqual(code.checkAuthorization({
    approvedVisits: 6,
    usedVisits: 4,
    startDate: "2026-02-01",
    endDate: "2026-04-30",
    visitDate: "2026-02-01"
  }), { covered: true, remaining: 1 });
});

test("visit one day before the start date is not covered and leaves 2", function () {
  assert.deepEqual(code.checkAuthorization({
    approvedVisits: 6,
    usedVisits: 4,
    startDate: "2026-02-01",
    endDate: "2026-04-30",
    visitDate: "2026-01-31"
  }), { covered: false, remaining: 2 });
});

test("visit one day after the start date is covered and leaves 1", function () {
  assert.deepEqual(code.checkAuthorization({
    approvedVisits: 6,
    usedVisits: 4,
    startDate: "2026-02-01",
    endDate: "2026-04-30",
    visitDate: "2026-02-02"
  }), { covered: true, remaining: 1 });
});

test("visit one day before the end date is covered and leaves 1", function () {
  assert.deepEqual(code.checkAuthorization({
    approvedVisits: 6,
    usedVisits: 4,
    startDate: "2026-02-01",
    endDate: "2026-04-30",
    visitDate: "2026-04-29"
  }), { covered: true, remaining: 1 });
});

test("visit is covered when used is one below approved and leaves 0", function () {
  assert.deepEqual(code.checkAuthorization({
    approvedVisits: 5,
    usedVisits: 4,
    startDate: "2026-02-01",
    endDate: "2026-04-30",
    visitDate: "2026-03-18"
  }), { covered: true, remaining: 0 });
});

test("visit is covered when zero visits are already used and leaves 6", function () {
  assert.deepEqual(code.checkAuthorization({
    approvedVisits: 7,
    usedVisits: 0,
    startDate: "2026-02-01",
    endDate: "2026-04-30",
    visitDate: "2026-03-11"
  }), { covered: true, remaining: 6 });
});

test("single approved visit on a single-day window is covered and leaves 0", function () {
  assert.deepEqual(code.checkAuthorization({
    approvedVisits: 1,
    usedVisits: 0,
    startDate: "2026-06-01",
    endDate: "2026-06-01",
    visitDate: "2026-06-01"
  }), { covered: true, remaining: 0 });
});

test("visit is not covered when approved and used are both zero and leaves 0", function () {
  assert.deepEqual(code.checkAuthorization({
    approvedVisits: 0,
    usedVisits: 0,
    startDate: "2026-06-01",
    endDate: "2026-06-30",
    visitDate: "2026-06-15"
  }), { covered: false, remaining: 0 });
});

test("visit on a leap day inclusive end date is covered and leaves 2", function () {
  assert.deepEqual(code.checkAuthorization({
    approvedVisits: 4,
    usedVisits: 1,
    startDate: "2024-02-01",
    endDate: "2024-02-29",
    visitDate: "2024-02-29"
  }), { covered: true, remaining: 2 });
});

test("visit one day after a leap day end date is not covered and leaves 3", function () {
  assert.deepEqual(code.checkAuthorization({
    approvedVisits: 4,
    usedVisits: 1,
    startDate: "2024-02-01",
    endDate: "2024-02-29",
    visitDate: "2024-03-01"
  }), { covered: false, remaining: 3 });
});

test("visit on the last day of December inside a year-crossing range is covered and leaves 6", function () {
  assert.deepEqual(code.checkAuthorization({
    approvedVisits: 11,
    usedVisits: 4,
    startDate: "2025-12-15",
    endDate: "2026-01-20",
    visitDate: "2025-12-31"
  }), { covered: true, remaining: 6 });
});

test("visit on the first of January inside a year-crossing range is covered and leaves 6", function () {
  assert.deepEqual(code.checkAuthorization({
    approvedVisits: 11,
    usedVisits: 4,
    startDate: "2025-12-15",
    endDate: "2026-01-20",
    visitDate: "2026-01-01"
  }), { covered: true, remaining: 6 });
});

test("an unknown field throws an error whose message names that field", function () {
  assert.throws(function () {
    code.checkAuthorization({
      approvedVisits: 6,
      usedVisits: 4,
      startDate: "2026-02-01",
      endDate: "2026-04-30",
      visitDate: "2026-03-15",
      notes: 1
    });
  }, /unknown field: notes/);
});
